function limitarTextoPorClasse(classe, limite = 120) {
  const elementos = document.querySelectorAll(`.${classe}`);

  elementos.forEach(elemento => {
    const textoOriginal = elemento.textContent.trim();
    if (textoOriginal.length > limite) {
      const textoCortado = textoOriginal.slice(0, limite - 3).trim();
      elemento.textContent = textoCortado + '...';
    }
  });
}

limitarTextoPorClasse('excerpt-trends');

function estilizarTitulosPorClasse(classe) {
  const titulos = document.querySelectorAll(`.${classe}`);

  titulos.forEach(titulo => {
    const texto = titulo.textContent.trim();
    const partes = texto.split(':');

    if (partes.length > 1) {
      const destaque = partes[0].trim();
      const restante = partes.slice(1).join(':').trim();

      titulo.innerHTML = `
        <span style="color: #FF6C0C;">${destaque}:</span>
        <span style="color: white;"> ${restante}</span>
      `;
    } else {
      titulo.innerHTML = `<span style="color: #FF6C0C;">${texto}</span>`;
    }
  });
}

// Executar
estilizarTitulosPorClasse('title-trends');

